ALTER TABLE users ADD COLUMN username TEXT;
CREATE UNIQUE INDEX users_username_unique ON users(lower(username)) WHERE username IS NOT NULL;
CREATE TABLE inventory_documents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,type TEXT NOT NULL CHECK(type IN ('receipt','issue','transfer','stocktake')),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','posted')),source_warehouse_id BIGINT REFERENCES warehouses(id),target_warehouse_id BIGINT REFERENCES warehouses(id),reason TEXT NOT NULL,created_by BIGINT NOT NULL REFERENCES users(id),approved_by BIGINT REFERENCES users(id),posted_by BIGINT REFERENCES users(id),version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),posted_at TIMESTAMPTZ);
CREATE TABLE inventory_document_items(document_id BIGINT REFERENCES inventory_documents(id),variant_id BIGINT REFERENCES product_variants(id),quantity INTEGER NOT NULL CHECK(quantity>=0),PRIMARY KEY(document_id,variant_id));
INSERT INTO permissions(code) VALUES('inventory.approve'),('inventory.post'),('content.read'),('content.write'),('content.approve'),('content.publish'),('content.manage'),('seo.manage'),('settings.read'),('settings.write'),('reports.read'),('payments.reconcile') ON CONFLICT DO NOTHING;
INSERT INTO roles(name) VALUES('writer'),('seo'),('finance'),('catalog_manager') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='admin' OR (r.name='writer' AND p.code IN ('content.read','content.write','media.read','media.upload')) OR (r.name='seo' AND p.code IN ('content.read','content.write','content.approve','content.publish','content.manage','seo.manage','media.read','media.upload')) OR (r.name='warehouse' AND p.code='inventory.post') OR (r.name='boss' AND p.code IN ('reports.read','content.read','settings.read')) OR (r.name='finance' AND p.code IN ('orders.read','payments.reconcile','reports.read')) OR (r.name='catalog_manager' AND p.code IN ('catalog.read','catalog.manage','catalog.create','catalog.edit','catalog.publish','catalog.archive','media.read','media.upload')) ON CONFLICT DO NOTHING;
